const raw = $input.first().json || {};

function parseJson(value, fallback) {
  if (value && typeof value === "object") { return value; }
  if (typeof value === "string" && value.trim()) {
    try { return JSON.parse(value); } catch (e) { return fallback; }
  }
  return fallback;
}

// Three shapes reach this node: a webhook POST (fields under body), a
// sub-workflow call (a JSON string in lead), and a direct manual run.
const fromSubWorkflow = raw.lead !== undefined;

const body = raw.body && typeof raw.body === "object" ? raw.body : null;
const headers = raw.headers || {};

// A fourth shape: the control plane's dispatch envelope. Recognised by carrying
// both a trace id and a lead OBJECT, which neither the webhook shape (lead
// fields at the top level) nor the sub-workflow shape (lead as a JSON string)
// does.
//
// Note which field is NOT trusted from it: nothing here decides authorization.
// organization_id arrives as execution data so this engine's own per-tenant
// state is scoped correctly, and the control plane already settled whether the
// caller may act on it before the payload was built.
const envelope = body && body.trace_id && body.lead && typeof body.lead === "object" ? body : null;
const fromControlPlane = envelope !== null;
const lead = fromControlPlane ? envelope.lead : (fromSubWorkflow ? parseJson(raw.lead, {}) : (body || raw));
const options = fromControlPlane
  ? {
      dry_run: String(envelope.dry_run),
      tenant_id: envelope.organization_id,
      trace_id: envelope.trace_id,
      enrich: "false"
    }
  : fromSubWorkflow
  ? parseJson(raw.options, {})
  : parseJson((body && body.options) || raw.options, {});

const email = String(lead.email || "").trim().toLowerCase();
const leadKey = email || "anonymous";

const dryRun = options.dry_run === undefined ? true : String(options.dry_run).toLowerCase() !== "false";

// Tenant comes from the caller, and on the public path from a header rather
// than the body, so a lead payload cannot choose which workspace it lands in.
const rawTenant = String(
  options.tenant_id || headers["x-tenant-id"] || headers["X-Tenant-Id"] || "default"
).trim().toLowerCase();
const tenantId = /^[a-z0-9][a-z0-9_-]{0,62}$/.test(rawTenant) ? rawTenant : "";

// One trace id per lead, generated here if the caller did not supply one, and
// threaded through every service so a run can be reassembled after the fact.
function rand() { return Math.random().toString(36).slice(2, 10); }
const traceId = String(options.trace_id || ("t-" + $execution.id + "-" + rand())).trim().slice(0, 64);

return [{ json: {
  lead: lead,
  lead_json: JSON.stringify(lead),
  lead_key: leadKey,
  email: email,
  tenant_id: tenantId,
  tenant_valid: !!tenantId,
  tenant_error: tenantId ? "" : ("tenant_id must match ^[a-z0-9][a-z0-9_-]{0,62}$; got " + JSON.stringify(rawTenant)),
  trace_id: traceId,
  entry: fromControlPlane ? "control_plane" : (fromSubWorkflow ? "sub_workflow" : (body ? "webhook" : "manual")),
  // Carried through so the completion can be signed and delivered. Absent for
  // every other entry shape, and the callback is then skipped rather than faked.
  callback_url: fromControlPlane ? String(envelope.callback_url || "") : "",
  callback_token: fromControlPlane ? String(envelope.callback_token || "") : "",
  saas_execution_id: fromControlPlane ? String(envelope.execution_id || "") : "",
  // The ceiling the control plane set. The engine may narrow this; it may never
  // widen it. An entry shape that does not set it is unconstrained by it.
  allowed_actions: fromControlPlane && Array.isArray(envelope.allowed_actions)
    ? envelope.allowed_actions.map(function (a) { return String(a); })
    : null,
  outreach_permitted: fromControlPlane && Array.isArray(envelope.allowed_actions)
    ? (envelope.allowed_actions.indexOf("outreach_draft") !== -1 || envelope.allowed_actions.indexOf("outreach_send") !== -1)
    : true,
  dry_run: dryRun,
  enrich: options.enrich === undefined ? false : String(options.enrich).toLowerCase() === "true",
  // Ownership boundary. When the control plane dispatched this run it had
  // already consulted its own executions table, where (org_id, idempotency_key)
  // is unique — so it has decided this is a new execution. n8n's lead ledger
  // must not then overrule that with a second, independent dedupe verdict;
  // two systems answering "have we seen this lead?" is how state becomes
  // ambiguous. Postgres owns lead identity; the ledger here is execution-local
  // bookkeeping and a CRM write lock.
  force: fromControlPlane
    ? true
    : (options.force === undefined ? false : String(options.force).toLowerCase() === "true"),
  channel: String(options.channel || "email").toLowerCase(),
  deal_stage: String(options.deal_stage || "qualifiedtobuy"),
  icp_json: options.icp ? JSON.stringify(options.icp) : "",
  rubric_override: options.rubric_override
    ? (typeof options.rubric_override === "string" ? options.rubric_override : JSON.stringify(options.rubric_override))
    : "",
  verification_mode: String(options.verification_mode || "deterministic_only"),
  simulate_decision: String(options.simulate_decision || ""),
  governance_action_type: String(options.governance_action_type || "send"),
  chat_id: String(options.chat_id || ""),
  signals_override: options.signals_override
    ? (typeof options.signals_override === "string" ? options.signals_override : JSON.stringify(options.signals_override))
    : "",
  started_at_ms: Date.now()
} }];

const req = $("Normalise Intake").first().json;
const row = $input.first().json || {};
return [{ json: {
  ok: true,
  outcome: "duplicate",
  trace_id: req.trace_id,
  tenant_id: req.tenant_id,
  lead_key: req.lead_key,
  email: req.email,
  message: "This lead was already processed on " + String(row.first_seen_at || "an earlier run") + ". Nothing was re-qualified and no CRM object was created. Pass options.force=true to run it again.",
  previous: {
    score: row.score === undefined ? null : row.score,
    tier: row.tier || null,
    contact_id: row.contact_id || null,
    deal_id: row.deal_id || null,
    status: row.status || null,
    trace_id: row.trace_id || null,
    first_seen_at: row.first_seen_at || null
  },
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const raw = $input.first().json;
const q = (raw && raw.json) ? raw.json : raw;
const req = $("Normalise Intake").first().json;

const lines = (q.scoring && q.scoring.components ? q.scoring.components : []).map(function (c) {
  return "  " + c.component + ": " + c.points + "/" + c.max + " (" + c.detail + ")";
});
(q.scoring && q.scoring.modifiers ? q.scoring.modifiers : []).forEach(function (m) {
  lines.push("  " + m.modifier + ": " + (m.points > 0 ? "+" : "") + m.points + " (" + m.reason + ")");
});
(q.scoring && q.scoring.caps_applied ? q.scoring.caps_applied : []).forEach(function (c) {
  lines.push("  capped at " + c.cap + ": " + c.reason);
});

// The task body is the audit trail a salesperson actually reads.
const rationale = "Lead score " + q.score + "/100 (" + q.tier + "), confidence " + q.confidence + ".\n\n" +
  "How the score was reached (rubric " + ((q.scoring || {}).rubric_version || "?") + "):\n" + lines.join("\n") +
  "\n\nRecommended action: " + q.recommended_action +
  (q.requires_human_review ? "\n\nNeeds review: " + (q.review_reasons || []).join("; ") : "") +
  "\n\nSignals were extracted by " + (((q.provenance || {}).model_provider) || "no model") +
  " and verified " + (((q.verification || {}).verified) ? "clean" : "with issues") + ".";

return [{ json: {
  qualification: q,
  qualification_json: JSON.stringify(q),
  score: q.score,
  tier: q.tier,
  confidence: q.confidence,
  recommended_action: q.recommended_action,
  outreach_allowed: q.outreach_allowed === true,
  requires_human_review: q.requires_human_review === true,
  actionable: q.tier !== "DISQUALIFIED",
  rationale: rationale,
  lead_key: req.lead_key
} }];

const raw = $input.first().json;
const r = (raw && raw.json) ? raw.json : raw;
return [{ json: {
  contact_id: String(r.object_id || ""),
  contact_status: r.status || "unknown",
  contact_ok: r.ok === true,
  contact_errors: r.errors || []
} }];

const raw = $input.first().json;
const r = (raw && raw.json) ? raw.json : raw;
return [{ json: {
  deal_id: String(r.object_id || ""),
  deal_status: r.status || "unknown",
  deal_ok: r.ok === true,
  deal_skipped_reason: ""
} }];

const q = $("Capture Qualification").first().json;
const c = $("Capture Contact").first().json;
return [{ json: {
  deal_id: "",
  deal_status: "not_created",
  deal_ok: false,
  deal_skipped_reason: c.contact_ok
    ? "a deal is only opened for a HOT lead; this one is " + q.tier
    : "the contact write did not return an id, so there is nothing to attach a deal to"
} }];

const req = $("Normalise Intake").first().json;
const q = $("Capture Qualification").first().json;
return [{ json: {
  ok: true,
  outcome: "disqualified",
  lead_key: q.lead_key,
  email: req.email,
  dry_run: req.dry_run,
  qualification: {
    score: q.score,
    tier: q.tier,
    confidence: q.confidence,
    recommended_action: q.recommended_action,
    requires_human_review: q.requires_human_review,
    review_reasons: (q.qualification || {}).review_reasons || [],
    scoring: (q.qualification || {}).scoring || {},
    verification: (q.qualification || {}).verification || {}
  },
  crm: { contact_id: "", contact_status: "not_written", deal_id: "", deal_status: "not_written", task_id: "", task_status: "not_written" },
  outreach: { attempted: false, sent: false, status: "not_attempted", detail: "the lead was disqualified", blocked_stage: null, blocked_reasons: [], draft: "", governance: {} },
  steps: [
    { step: "qualify", done: true, detail: "score " + q.score + " (" + q.tier + ")" },
    { step: "crm_contact", done: false, detail: "a disqualified lead is never written to the CRM" },
    { step: "crm_deal", done: false, detail: "a disqualified lead is never written to the CRM" },
    { step: "crm_task", done: false, detail: "a disqualified lead is never written to the CRM" },
    { step: "outreach", done: false, detail: "a disqualified lead is never written to" }
  ],
  entry: req.entry,
  execution_id: $execution.id,
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const raw = $input.first().json;
const r = (raw && raw.json) ? raw.json : raw;
return [{ json: {
  task_id: String(r.object_id || ""),
  task_status: r.status || "unknown",
  task_ok: r.ok === true
} }];

const raw = $input.first().json;
const r = (raw && raw.json) ? raw.json : raw;
return [{ json: {
  outreach_attempted: true,
  outreach_sent: r.sent === true,
  outreach_status: r.delivery_status || "unknown",
  outreach_detail: r.delivery_detail || "",
  outreach_blocked_stage: r.blocked_stage || null,
  outreach_blocked_reasons: r.blocked_reasons || [],
  outreach_draft: r.draft || "",
  outreach_governance: r.governance || {},
  outreach_skipped_reason: ""
} }];

const q = $("Capture Qualification").first().json;
return [{ json: {
  outreach_attempted: false,
  outreach_sent: false,
  outreach_status: "not_attempted",
  outreach_detail: "",
  outreach_blocked_stage: null,
  outreach_blocked_reasons: [],
  outreach_draft: "",
  outreach_governance: {},
  outreach_skipped_reason: (q.qualification || {}).outreach_block_reason || "qualification did not allow outreach"
} }];

const req = $("Normalise Intake").first().json;
const q = $("Capture Qualification").first().json;

function safe(nodeName) {
  try { return $(nodeName).first().json; } catch (e) { return {}; }
}
function ran(nodeName) {
  try { return $(nodeName).isExecuted; } catch (e) { return false; }
}

// One builder for both outcomes. Two builders drift; this one cannot.
const disqualified = ran("Record Disqualified");

const contact = disqualified ? {} : safe("Capture Contact");
const deal = disqualified ? {} : (ran("Capture Deal") ? safe("Capture Deal") : safe("Skip Deal"));
const task = disqualified ? {} : safe("Capture Task");
const outreach = disqualified ? {} : (ran("Capture Outreach") ? safe("Capture Outreach") : safe("Skip Outreach"));

const NO_CRM = "a disqualified lead is never written to the CRM";
const steps = [];
steps.push({ step: "qualify", done: true, detail: "score " + q.score + " (" + q.tier + "), confidence " + q.confidence });
steps.push({ step: "crm_contact", done: contact.contact_ok === true, detail: disqualified ? NO_CRM : (contact.contact_status + (contact.contact_id ? " as " + contact.contact_id : "")) });
steps.push({ step: "crm_deal", done: deal.deal_ok === true, detail: disqualified ? NO_CRM : (deal.deal_ok ? deal.deal_status + " as " + deal.deal_id : deal.deal_skipped_reason) });
steps.push({ step: "crm_task", done: task.task_ok === true, detail: disqualified ? NO_CRM : ((task.task_status || "not_run") + (task.task_id ? " as " + task.task_id : "")) });
steps.push({ step: "outreach", done: outreach.outreach_attempted === true, detail: disqualified ? "a disqualified lead is never written to" : (outreach.outreach_attempted ? (outreach.outreach_status + ": " + outreach.outreach_detail) : outreach.outreach_skipped_reason) });

const full = q.qualification || {};
const providers = [];
if ((full.provenance || {}).model_provider) { providers.push("qualify:" + full.provenance.model_provider); }
if ((outreach.outreach_governance || {}).decided_by) { providers.push("govern:" + outreach.outreach_governance.decided_by); }

return [{ json: {
  ok: true,
  outcome: disqualified ? "disqualified" : "processed",
  trace_id: req.trace_id,
  tenant_id: req.tenant_id,
  lead_key: q.lead_key,
  email: req.email,
  company_domain: full.company_domain || "",
  dry_run: req.dry_run,
  tenant_error: req.tenant_error || "",
  qualification: {
    score: q.score,
    tier: q.tier,
    confidence: q.confidence,
    recommended_action: q.recommended_action,
    requires_human_review: q.requires_human_review,
    review_reasons: full.review_reasons || [],
    scoring: full.scoring || {},
    grounding: full.grounding || {},
    verification: full.verification || {}
  },
  crm: {
    contact_id: contact.contact_id || "",
    contact_status: disqualified ? "not_written" : (contact.contact_status || "not_run"),
    deal_id: deal.deal_id || "",
    deal_status: disqualified ? "not_written" : (deal.deal_status || "not_run"),
    task_id: task.task_id || "",
    task_status: disqualified ? "not_written" : (task.task_status || "not_run")
  },
  outreach: {
    attempted: outreach.outreach_attempted === true,
    sent: outreach.outreach_sent === true,
    status: disqualified ? "not_attempted" : (outreach.outreach_status || "not_attempted"),
    detail: disqualified ? "the lead was disqualified" : (outreach.outreach_detail || outreach.outreach_skipped_reason || ""),
    blocked_stage: outreach.outreach_blocked_stage || null,
    blocked_reasons: outreach.outreach_blocked_reasons || [],
    draft: outreach.outreach_draft || "",
    governance: outreach.outreach_governance || {}
  },
  model_providers: providers.join(", "),
  steps: steps,
  entry: req.entry,
  execution_id: $execution.id,
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

// Second layer.
//
// The PRIMARY gate is the webhook node's own header auth credential, which n8n
// enforces before this workflow runs at all: a request without the right
// x-swarm-key never reaches this node. That is stronger than what used to be
// here, which compared against $vars.SWARM_INGEST_KEY — and n8n variables are a
// licensed feature this instance does not have, so that comparison could never
// succeed and the endpoint refused every lead (verified in execution 1033).
//
// The credential cannot be read from a Code node, by design. So this node no
// longer re-checks the secret; it checks the things it still can see, and the
// invariant that the webhook is actually configured with authentication is
// enforced in CI against the exported workflow instead.
const item = $input.first().json || {};
const headers = item.headers || {};

// If a licensed instance does set the variable, keep honouring it as a real
// second factor. If it is unset, the edge gate already ran.
let expected = "";
try { expected = String(($vars && $vars.SWARM_INGEST_KEY) || ""); } catch (e) { expected = ""; }
const supplied = String(headers["x-swarm-key"] || headers["X-Swarm-Key"] || "");

let authorised = true;
let reason = "";
let gate = "webhook_header_auth";

if (expected) {
  gate = "webhook_header_auth + instance_variable";
  if (supplied.length !== expected.length) {
    authorised = false;
    reason = "the x-swarm-key header did not match the instance variable";
  } else {
    let diff = 0;
    for (let i = 0; i < expected.length; i++) { diff |= expected.charCodeAt(i) ^ supplied.charCodeAt(i); }
    authorised = diff === 0;
    if (!authorised) { reason = "the x-swarm-key header did not match the instance variable"; }
  }
}

// A tenant must be named, and the character set is restricted rather than
// escaped so it cannot smuggle a separator into a composite key downstream.
const rawTenant = String(headers["x-tenant-id"] || headers["X-Tenant-Id"] || "").trim().toLowerCase();
if (authorised && rawTenant && !/^[a-z0-9][a-z0-9_-]{0,62}$/.test(rawTenant)) {
  authorised = false;
  reason = "x-tenant-id must match ^[a-z0-9][a-z0-9_-]{0,62}$";
}

item.ingest_authorised = authorised;
item.ingest_reason = reason;
item.ingest_gate = gate;
return [{ json: item }];

return [{ json: {
  ok: false,
  outcome: "unauthorised",
  message: "Lead rejected: " + String($json.ingest_reason || "no reason recorded") + ".",
  hint: "Set an n8n variable named SWARM_INGEST_KEY and send it as the x-swarm-key header."
} }];

// A run nonce keeps the ledger dedupe honest: S01 is always a fresh lead and
// S02 is always the same lead a second time.
const nonce = String($execution.id) + Date.now().toString(36);

function sig(o) {
  const base = { seniority: "unknown", decision_authority: "unknown", company_size_band: "unknown", budget_signal: "unknown", timeline: "unknown", pain_specificity: "unknown", use_case_fit: "unknown", competitor_mentioned: false, evidence: [], notes: "fixture" };
  return JSON.stringify(Object.assign(base, o));
}

const HOT = { seniority: "executive", decision_authority: "decision_maker", company_size_band: "201-1000", budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific", use_case_fit: "core", evidence: [{ signal: "budget_signal", quote: "We have 30k set aside" }] };
const WARM = { seniority: "manager", decision_authority: "influencer", company_size_band: "51-200", budget_signal: "implied", timeline: "this_quarter", pain_specificity: "general", use_case_fit: "adjacent" };
const COLD = { seniority: "ic", decision_authority: "end_user", company_size_band: "11-50", budget_signal: "none", timeline: "this_year", pain_specificity: "general", use_case_fit: "adjacent" };
const OUT = { seniority: "executive", decision_authority: "decision_maker", company_size_band: "201-1000", budget_signal: "explicit", timeline: "immediate", pain_specificity: "specific", use_case_fit: "out_of_scope" };

function lead(prefix, extra) {
  return Object.assign({
    email: prefix + "-" + nonce + "@analytical.io",
    first_name: "Ada",
    last_name: "Lovelace",
    job_title: "VP of Engineering",
    company_name: "Analytical Engines",
    message: "We have 30k set aside and need this live this month."
  }, extra || {});
}

const hotLead = lead("s01");

const fixtures = [
  { case_id: "S01", note: "a HOT lead gets a contact, a deal, a scored task and a drafted message", lead: hotLead, tenant: "acme", signals: sig(HOT), expect_outcome: "processed", expect_tier: "HOT", expect_deal: true, expect_outreach: true, expect_contact: true },
  { case_id: "S02", note: "the same lead a second time is not re-qualified", lead: hotLead, tenant: "acme", signals: sig(HOT), expect_outcome: "duplicate", expect_tier: null, expect_deal: false, expect_outreach: false, expect_contact: false },
  { case_id: "S03", note: "a WARM lead gets a contact and a task but no deal", lead: lead("s03"), tenant: "acme", signals: sig(WARM), expect_outcome: "processed", expect_tier: "WARM", expect_deal: false, expect_outreach: true, expect_contact: true },
  { case_id: "S04", note: "a disqualified lead is never written to the CRM", lead: lead("s04"), tenant: "acme", signals: sig(OUT), expect_outcome: "disqualified", expect_tier: "DISQUALIFIED", expect_deal: false, expect_outreach: false, expect_contact: false },
  { case_id: "S05", note: "a COLD lead is recorded but not written to", lead: lead("s05"), tenant: "acme", signals: sig(COLD), expect_outcome: "processed", expect_tier: "COLD", expect_deal: false, expect_outreach: false, expect_contact: true },
  { case_id: "S06", note: "live: the whole pipeline with the real model, structure only", lead: lead("s06"), tenant: "acme", signals: "", expect_outcome: null, expect_tier: null, expect_deal: null, expect_outreach: null, expect_contact: true },
  { case_id: "S07", note: "a second workspace sending the identical lead is processed, not deduplicated", lead: hotLead, tenant: "globex", signals: sig(HOT), expect_outcome: "processed", expect_tier: "HOT", expect_deal: true, expect_outreach: true, expect_contact: true }
];

return fixtures.map(function (f) {
  return { json: {
    case_id: f.case_id,
    note: f.note,
    tenant_id: f.tenant,
    trace_id: "trace-" + nonce + "-" + f.case_id,
    lead: JSON.stringify(f.lead),
    options: JSON.stringify({
      dry_run: true,
      enrich: false,
      channel: "email",
      simulate_decision: "approve",
      signals_override: f.signals,
      tenant_id: f.tenant,
      trace_id: "trace-" + nonce + "-" + f.case_id
    }),
    expect_outcome: f.expect_outcome,
    expect_tier: f.expect_tier,
    expect_deal: f.expect_deal,
    expect_outreach: f.expect_outreach,
    expect_contact: f.expect_contact
  } };
});

const rows = $input.all().map(function (i) { return i.json; });
const byCase = {};
rows.forEach(function (r) { byCase[r.case_id] = r; });

const cases = rows.map(function (r) {
  const checks = [];
  const isDuplicate = r.expect_outcome === "duplicate";
  if (r.expect_outcome === null) {
    checks.push({ name: "outcome_known", pass: ["processed", "disqualified"].indexOf(r.actual_outcome) !== -1, expected: "processed|disqualified", actual: r.actual_outcome });
    checks.push({ name: "score_in_range", pass: typeof r.actual_score === "number" && r.actual_score >= 0 && r.actual_score <= 100, expected: "0..100", actual: r.actual_score });
    checks.push({ name: "never_sent_in_dry_run", pass: r.outreach_sent === false, expected: false, actual: r.outreach_sent });
    checks.push({ name: "decision_record_complete", pass: r.steps === 5, expected: 5, actual: r.steps });
  } else {
    checks.push({ name: "outcome", pass: r.actual_outcome === r.expect_outcome, expected: r.expect_outcome, actual: r.actual_outcome });
    if (r.expect_tier) {
      checks.push({ name: "tier", pass: r.actual_tier === r.expect_tier, expected: r.expect_tier, actual: r.actual_tier });
    }
    checks.push({ name: "contact_written", pass: r.has_contact === r.expect_contact, expected: r.expect_contact, actual: r.has_contact });
    checks.push({ name: "deal_written", pass: r.has_deal === r.expect_deal, expected: r.expect_deal, actual: r.has_deal });
    checks.push({ name: "outreach_attempted", pass: r.outreach_attempted === r.expect_outreach, expected: r.expect_outreach, actual: r.outreach_attempted });
    checks.push({ name: "never_sent_in_dry_run", pass: r.outreach_sent === false, expected: false, actual: r.outreach_sent });
    if (!isDuplicate) {
      checks.push({ name: "decision_record_complete", pass: r.steps === 5, expected: 5, actual: r.steps });
      checks.push({ name: "rubric_recorded", pass: !!r.rubric_version, expected: "a rubric version", actual: r.rubric_version });
    }
  }
  // Correlation: every response, duplicate included, must name its workspace.
  checks.push({ name: "tenant_echoed", pass: r.actual_tenant === r.expect_tenant, expected: r.expect_tenant, actual: r.actual_tenant });
  if (!isDuplicate) {
    checks.push({ name: "trace_echoed", pass: r.actual_trace === r.expect_trace, expected: r.expect_trace, actual: r.actual_trace });
  }
  const failed = checks.filter(function (c) { return !c.pass; });
  return { case_id: r.case_id, note: r.note, passed: failed.length === 0, checks: checks, latency_ms: r.latency_ms };
});

// Workspace isolation is a property of the pair, not of either case alone.
const s01 = byCase["S01"];
const s07 = byCase["S07"];
if (s01 && s07) {
  cases.push({
    case_id: "S07x",
    note: "workspace isolation: an identical lead in a second workspace is not suppressed",
    passed: s01.actual_outcome === "processed" && s07.actual_outcome === "processed" && s01.actual_tenant !== s07.actual_tenant,
    checks: [
      { name: "first_workspace_processed", pass: s01.actual_outcome === "processed", expected: "processed", actual: s01.actual_outcome },
      { name: "second_workspace_processed", pass: s07.actual_outcome === "processed", expected: "processed", actual: s07.actual_outcome },
      { name: "workspaces_distinct", pass: s01.actual_tenant !== s07.actual_tenant, expected: "acme != globex", actual: s01.actual_tenant + " vs " + s07.actual_tenant }
    ],
    latency_ms: s07.latency_ms
  });
}

const passed = cases.filter(function (c) { return c.passed; }).length;
return [{ json: {
  suite: "14-revenue-swarm",
  run_at: new Date().toISOString(),
  execution_id: $execution.id,
  total: cases.length,
  passed: passed,
  failed: cases.length - passed,
  all_passed: passed === cases.length && cases.length === 8,
  cases: cases
} }];

// The receipt write emits a database row. Re-emit the response so the webhook
// and any sub-workflow caller receive the decision, not the row id.
return $("Build Swarm Response").all();

function sha256Bytes(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,
      h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;

  const ml = bytes.length * 8;
  const withPad = bytes.slice();
  withPad.push(0x80);
  while (withPad.length % 64 !== 56) { withPad.push(0); }
  // 64-bit big-endian length. Messages here are far below 2^32 bits, so the
  // high word is zero, but write it explicitly rather than assuming.
  const hi = Math.floor(ml / 4294967296);
  withPad.push((hi>>>24)&255,(hi>>>16)&255,(hi>>>8)&255,hi&255);
  withPad.push((ml>>>24)&255,(ml>>>16)&255,(ml>>>8)&255,ml&255);

  const w = new Array(64);
  function rotr(x,n){ return ((x>>>n)|(x<<(32-n)))>>>0; }

  for (let i = 0; i < withPad.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = ((withPad[i+t*4]<<24)|(withPad[i+t*4+1]<<16)|(withPad[i+t*4+2]<<8)|withPad[i+t*4+3])>>>0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = (rotr(w[t-15],7) ^ rotr(w[t-15],18) ^ (w[t-15]>>>3))>>>0;
      const s1 = (rotr(w[t-2],17) ^ rotr(w[t-2],19) ^ (w[t-2]>>>10))>>>0;
      w[t] = (((w[t-16]+s0)>>>0) + ((w[t-7]+s1)>>>0))>>>0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e,6) ^ rotr(e,11) ^ rotr(e,25))>>>0;
      const ch = ((e & f) ^ (~e & g))>>>0;
      const t1 = (((((h + S1)>>>0) + ch)>>>0) + ((K[t] + w[t])>>>0))>>>0;
      const S0 = (rotr(a,2) ^ rotr(a,13) ^ rotr(a,22))>>>0;
      const maj = ((a & b) ^ (a & c) ^ (b & c))>>>0;
      const t2 = ((S0 + maj)>>>0);
      h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    h0=(h0+a)>>>0; h1=(h1+b)>>>0; h2=(h2+c)>>>0; h3=(h3+d)>>>0;
    h4=(h4+e)>>>0; h5=(h5+f)>>>0; h6=(h6+g)>>>0; h7=(h7+h)>>>0;
  }

  const out = [];
  [h0,h1,h2,h3,h4,h5,h6,h7].forEach(function (v) {
    out.push((v>>>24)&255,(v>>>16)&255,(v>>>8)&255,v&255);
  });
  return out;
}

function utf8Bytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c < 0x80) { out.push(c); }
    else if (c < 0x800) { out.push(0xc0|(c>>6), 0x80|(c&63)); }
    else if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const c2 = str.charCodeAt(i+1);
      const cp = 0x10000 + ((c - 0xd800) << 10) + (c2 - 0xdc00);
      out.push(0xf0|(cp>>18), 0x80|((cp>>12)&63), 0x80|((cp>>6)&63), 0x80|(cp&63));
      i++;
    }
    else { out.push(0xe0|(c>>12), 0x80|((c>>6)&63), 0x80|(c&63)); }
  }
  return out;
}

function toHex(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) {
    s += (bytes[i] < 16 ? '0' : '') + bytes[i].toString(16);
  }
  return s;
}

function sha256Hex(str) { return toHex(sha256Bytes(utf8Bytes(str))); }

function hmacSha256Hex(secret, message) {
  const block = 64;
  let key = utf8Bytes(secret);
  if (key.length > block) { key = sha256Bytes(key); }
  while (key.length < block) { key.push(0); }
  const ipad = [], opad = [];
  for (let i = 0; i < block; i++) {
    ipad.push(key[i] ^ 0x36);
    opad.push(key[i] ^ 0x5c);
  }
  const inner = sha256Bytes(ipad.concat(utf8Bytes(message)));
  return toHex(sha256Bytes(opad.concat(inner)));
}


const intake = $("Normalise Intake").first().json;
const response = $("Build Swarm Response").first().json;

// No callback_url means this run did not come from the control plane (a direct
// webhook post, or the test suite). Emit a marker the IF node routes on.
if (!intake.callback_url || !intake.callback_token) {
  return [{ json: { callback_skipped: true, reason: "no callback_url in the dispatch payload" } }];
}

const q = response.qualification || {};
const scoring = q.scoring || {};
const grounding = q.grounding || {};
const crm = response.crm || {};
const outreach = response.outreach || {};

// Evidence: every quoted span the model returned, marked with whether the
// deterministic check found it in the source text. The unsupported ones are
// kept, not dropped — why a lead lost points is part of the audit trail.
const unsupported = {};
(grounding.unsupported_evidence || []).forEach(function (e) {
  unsupported[String(e.signal) + "|" + String(e.quote)] = true;
});
const evidence = ((q.signals || {}).evidence || []).map(function (e) {
  const key = String(e.signal) + "|" + String(e.quote);
  return {
    signal: String(e.signal || ""),
    value: String((q.signals || {})[e.signal] || ""),
    quote: e.quote === undefined ? null : String(e.quote),
    source_field: "message",
    supported: !unsupported[key],
    points: 0
  };
});

const components = (scoring.components || []).map(function (c) {
  return {
    signal: String(c.component || ""),
    value: String(c.detail || ""),
    points: Math.round(Number(c.points) || 0),
    supported: true
  };
});
(scoring.modifiers || []).forEach(function (m) {
  components.push({
    signal: String(m.modifier || "modifier"),
    value: String(m.reason || ""),
    points: Math.round(Number(m.points) || 0),
    supported: false
  });
});

const taken = [];
if (crm.contact_id) {
  taken.push({ action: "crm_upsert_contact", object_id: String(crm.contact_id), status: String(crm.contact_status || "") });
}
if (crm.deal_id) {
  taken.push({ action: "crm_create_deal", object_id: String(crm.deal_id), status: String(crm.deal_status || "") });
}
if (crm.task_id) {
  taken.push({ action: "crm_create_task", object_id: String(crm.task_id), status: String(crm.task_status || "") });
}
if (outreach.sent) {
  taken.push({ action: "outreach_send", status: String(outreach.status || "") });
}

// Every step that did not happen carries the reason it did not happen. A
// skipped step with no reason is a missing audit record, and the control
// plane's schema refuses it.
const skipped = [];
(response.steps || []).forEach(function (s) {
  if (!s.done) {
    skipped.push({
      action: String(s.step || "unknown"),
      reason: String(s.detail || "no reason recorded")
    });
  }
});
if (!outreach.attempted && !skipped.some(function (s) { return s.action === "outreach"; })) {
  skipped.push({ action: "outreach", reason: String(outreach.detail || "outreach was not attempted") });
}

const payload = {
  status: response.ok === false ? "failed" : "succeeded",
  decision: String(response.outcome || "unknown"),
  score: q.score === undefined || q.score === null ? null : Math.round(Number(q.score)),
  tier: q.tier || null,
  rubric_version: scoring.rubric_version || null,
  prompt_versions: (q.provenance && q.provenance.prompt_sha)
    ? { "revenue/lead-qualifier": String(q.provenance.prompt_sha) }
    : {},
  model_metadata: (q.provenance && q.provenance.model_provider)
    ? { provider: String(q.provenance.model_provider) }
    : {},
  score_components: components,
  evidence: evidence,
  verification: q.verification || {},
  governance: outreach.governance || {},
  actions_taken: taken,
  actions_skipped: skipped,
  crm_result: crm,
  engine_execution_id: String($execution.id)
};

const body = JSON.stringify(payload);

// The signature binds method, path, time, a single-use nonce and a digest of
// the exact bytes below. The control plane recomputes it over the raw body it
// receives, so re-serialising anywhere in between would invalidate it.
const url = intake.callback_url;
const path = url.replace(/^https?:\/\/[^/]+/, "");
const timestamp = String(Math.floor(Date.now() / 1000));
let nonce = "";
const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789";
for (let i = 0; i < 24; i++) { nonce += alphabet[Math.floor(Math.random() * alphabet.length)]; }

const digest = sha256Hex(body);
const canonical = "v1:POST:" + path + ":" + timestamp + ":" + nonce + ":" + digest;
const signature = "v1=" + hmacSha256Hex(String(intake.callback_token), canonical);

return [{ json: {
  callback_skipped: false,
  callback_url: url,
  callback_body: body,
  signature: signature,
  timestamp: timestamp,
  nonce: nonce,
  trace_id: String(intake.trace_id || "")
} }];
